  20	impl<'a> Part<'a> {
  21	    /// Returns the exact byte length of given part.
  22	    pub fn len(&self) -> usize {
  23	        match *self {
  24	            Part::Zero(nzeroes) => nzeroes,
  25	            Part::Num(v) => v.checked_ilog10().unwrap_or_default() as usize + 1,
  26	            Part::Copy(buf) => buf.len(),
